// Generated by tools/build_ui.py for Airwindows Dithers, option B+A+C. Do not edit.
// Shared drawing library for the Airwindows device UIs.
// Loaded by the review page (index.html) and, through the mgraphics adapter, by the
// v8ui display inside each Max for Live device. No DOM access in this file.

const S = { themes: null, reg: [], byCat: {}, decisions: {}, theme: "dark", zoom: 2, mocks: [] };

// Hover hints (Live's Info View). Coordinates are canvas units (header included). S.offX is
// the x offset of the view being drawn when several views share one device.
S.hints = [];
S.offX = 0;
function hint(x, y, w, h, title, text) { S.hints.push({ x: x + S.offX, y, w, h, title, text }); }

const FONT = '"Ableton Sans Small", -apple-system, sans-serif';
const DEVICE_H = 169;   // Live's device body height
const HEAD_H = 18;      // device title bar

// ---------------------------------------------------------------- theme
function tok() {
  const t = S.themes[S.theme];
  const light = S.theme === "light";
  return {
    body: t.DetailViewBackground, text: t.ControlForeground, dim: light ? "#3d3d3d" : "#8a8a8a",
    display: t.RetroDisplayBackground, dline: t.RetroDisplayBackgroundLine,
    orange: t.RetroDisplayForeground, cyan: t.RetroDisplayForeground2, arc: t.RangeDefault,
    track: light ? "#8f8f8f" : "#1e1e1e", needle: light ? "#121212" : "#d9d9d9",
    ctrlBg: t.ControlBackground, frame: light ? "#4f4f4f" : "#111111", on: t.ViewControlOn,
    meterBg: t.MeterBackground, scale: t.RetroDisplayScaleText.slice(0, 7), title: t.RetroDisplayTitle,
    dispText: light ? "#cfcfcf" : "#b5b5b5", panel: light ? "rgba(0,0,0,0.08)" : "rgba(0,0,0,0.18)",
    green: "#1ec15a", greenDim: "#0f6b33",
  };
}

// ---------------------------------------------------------------- signal simulation
// A drum loop at 120 bpm: kick on beats, snare on 2 and 4, hats on eighths.
function drums(t) {
  const beat = 0.5, ph = t % (beat * 4);
  const kick = Math.exp(-((ph % beat)) * 9);
  const sn = [beat, beat * 3].map(s => (ph >= s ? Math.exp(-(ph - s) * 14) : 0)).reduce((a, b) => a + b);
  const hat = Math.exp(-((ph % (beat / 2))) * 40) * 0.35;
  return { kick, sn, hat, env: Math.min(1, kick * 0.9 + sn * 0.7 + hat) };
}
const db = a => 20 * Math.log10(Math.max(a, 1e-5));
function noise(i) { const x = Math.sin(i * 12.9898) * 43758.5453; return (x - Math.floor(x)) * 2 - 1; }

// ---------------------------------------------------------------- drawing helpers
function rr(c, x, y, w, h, r, fill, stroke) {
  c.beginPath(); c.roundRect(x, y, w, h, r);
  if (fill) { c.fillStyle = fill; c.fill(); }
  if (stroke) { c.strokeStyle = stroke; c.lineWidth = 1; c.stroke(); }
}
function txt(c, x, y, s, o = {}) {
  c.font = `${o.bold ? 700 : 400} ${o.size || 9.5}px ${FONT}`;
  c.fillStyle = o.color; c.textAlign = o.align || "center"; c.textBaseline = o.base || "alphabetic";
  c.fillText(s, x, y);
}
function fmt(display) {
  const m = String(display).match(/^(-?\d+\.\d+)(.*)/);
  return m ? parseFloat(m[1]).toFixed(2) + m[2] : display;
}
function shortName(n) { return n.length > 9 ? n.slice(0, 8) + "." : n; }

// Live-style dial: label above, 270° arc, needle, value below. Cell is w x 50.
function knob(c, th, x, y, w, p, v, big = false) {
  const r = big ? 15 : 11, cx = x + w / 2, cy = y + (big ? 30 : 25);
  hint(x, y, w, big ? 58 : 50, p.name, p.info || `A control of ${S.effName || "this effect"}. ${S.effWhat || ""}`.trim());
  txt(c, cx, y + 9, shortName(p.name), { color: th.text });
  const a0 = Math.PI * 0.75, a1 = Math.PI * 2.25, av = a0 + (a1 - a0) * v;
  c.lineCap = "butt";
  c.beginPath(); c.arc(cx, cy, r, a0, a1); c.strokeStyle = th.track; c.lineWidth = big ? 3 : 2.5; c.stroke();
  c.beginPath(); c.arc(cx, cy, r, a0, av); c.strokeStyle = th.arc; c.lineWidth = big ? 3.5 : 3; c.stroke();
  c.beginPath(); c.moveTo(cx + Math.cos(av) * r * 0.25, cy + Math.sin(av) * r * 0.25);
  c.lineTo(cx + Math.cos(av) * (r - 1), cy + Math.sin(av) * (r - 1));
  c.strokeStyle = th.needle; c.lineWidth = 2; c.lineCap = "round"; c.stroke(); c.lineCap = "butt";
  txt(c, cx, cy + r + (big ? 13 : 12), fmt(p.display), { color: th.text });
}
function menu(c, th, x, y, w, label) {
  label = S.effName || label;   // always show the effect being previewed
  hint(x, y, w, 15, "Effect", `Chooses which Airwindows effect this device runs. Now: ${label}. ${S.effWhat || ""}`.trim());
  rr(c, x + 0.5, y + 0.5, w, 14, 1, th.ctrlBg, th.frame);
  txt(c, x + 4, y + 11, label, { color: th.text, align: "left" });
  c.fillStyle = th.text; c.beginPath(); c.moveTo(x + w - 10, y + 5); c.lineTo(x + w - 3, y + 5); c.lineTo(x + w - 6.5, y + 10); c.fill();
}
function arrows(c, th, x, y) {
  hint(x, y, 30, 15, "Previous / Next Effect", "Steps to the previous or next effect in the menu.");
  for (const [i, d] of [[0, -1], [1, 1]]) {
    const bx = x + i * 15;
    rr(c, bx + 0.5, y + 0.5, 14, 14, 1, th.ctrlBg, th.frame);
    c.fillStyle = th.text; c.beginPath();
    c.moveTo(bx + 7 - 2.5 * d, y + 4); c.lineTo(bx + 7 + 2.5 * d, y + 7.5); c.lineTo(bx + 7 - 2.5 * d, y + 11); c.fill();
  }
}
function toggle(c, th, x, y, w, label, on) {
  rr(c, x + 0.5, y + 0.5, w, 14, 1, on ? th.on : th.ctrlBg, th.frame);
  txt(c, x + w / 2, y + 11, label, { color: on ? "#121212" : th.text });
}
function header(c, th, w, title) {
  c.fillStyle = th.body; c.fillRect(0, 0, w, HEAD_H + DEVICE_H);
  c.beginPath(); c.arc(10, 9, 5.5, 0, Math.PI * 2); c.fillStyle = th.on; c.fill();
  c.strokeStyle = th.frame; c.lineWidth = 1; c.stroke();
  txt(c, 21, 13, title, { bold: true, size: 11, color: th.text, align: "left" });
  c.strokeStyle = S.theme === "light" ? "#a5a5a5" : "#2a2a2a"; c.beginPath(); c.moveTo(0, HEAD_H - 0.5); c.lineTo(w, HEAD_H - 0.5); c.stroke();
}
// vertical meter: value 0..1 lit from the bottom (green), or from the top for gain reduction (orange)
function meterV(c, th, x, y, w, h, v, fromTop = false, color) {
  c.fillStyle = th.meterBg; c.fillRect(x, y, w, h);
  const lit = Math.max(0, Math.min(1, v)) * h;
  c.fillStyle = color || th.green;
  if (fromTop) c.fillRect(x, y, w, lit); else c.fillRect(x, y + h - lit, w, lit);
}
// Knob grid: place params left-to-right, top-to-bottom inside an area.
function knobGrid(c, th, params, area, cols, vals, cellW = 52) {
  // too many controls for the height: add columns and narrow the cells
  const fitRows = Math.max(1, Math.floor(area.h / 48));
  if (Math.ceil(params.length / cols) > fitRows) {
    cols = Math.ceil(params.length / fitRows);
    cellW = Math.min(cellW, area.w / cols);
  }
  const rows = Math.ceil(params.length / cols) || 1;
  const cellH = Math.min(52, area.h / rows);
  params.forEach((p, i) => {
    const r = Math.floor(i / cols), k = i % cols;
    const inRow = Math.min(cols, params.length - r * cols);
    const x = area.x + (area.w - inRow * cellW) / 2 + k * cellW;
    const y = area.y + (area.h - rows * cellH) / 2 + r * cellH;
    knob(c, th, x, y, cellW, p, vals[p._i]);
  });
}

// ---------------------------------------------------------------- shared state per mock
function newState() { return { t: 0, hist: [], gr: 0, inL: -60, outL: -60, peakIn: -60, peakOut: -60, tail: 0, decayHist: [] }; }
function stepDynamics(st, dt) {
  const d = drums(st.t);
  const inDb = db(d.env * 0.9 + 0.02);
  const thr = -14, ratio = 4;
  const target = Math.max(0, inDb - thr) * (1 - 1 / ratio);
  st.gr += (target - st.gr) * (target > st.gr ? 0.6 : 0.08);          // attack / release
  st.inL = Math.max(inDb, st.inL - 24 * dt); st.outL = Math.max(inDb - st.gr + 3, st.outL - 24 * dt);
  st.hist.push({ inA: d.env, out: st.outL, gr: st.gr });
  st.hist.simThr = true;
  if (st.hist.length > 600) st.hist.shift();
}
function stepReverb(st, dt) {
  const d = drums(st.t);
  st.tail = st.tail * Math.exp(-dt / 0.55) + (d.kick > 0.95 || d.sn > 0.95 ? 0.6 : 0) + d.env * 0.02;
  const n = st.hist.length;
  const wet = Math.min(1, st.tail) * (0.55 + 0.45 * Math.abs(noise(n * 0.37)));
  st.hist.push({ dry: d.env, wet });
  if (st.hist.length > 800) st.hist.shift();
  st.inL = Math.max(db(d.env * 0.8 + 0.01), st.inL - 24 * dt); st.outL = Math.max(db(Math.min(1, st.tail) * 0.8 + 0.01), st.outL - 24 * dt);
}

// ---------------------------------------------------------------- real measurements
// One display frame from airwin~ (about 30 per second), the same in the device and in the
// review page's "Real audio" mode (frames recorded with `awtool frames`):
//   m.inPkDb[2], m.outPkDb[2]   peak level per channel, dBFS (-120 = silence)
//   m.inRmsDb, m.outRmsDb       RMS of the mono sum, dBFS
//   m.gainDb                    outRms - inRms (0 when the input is silent)
//   m.corr                      output L/R correlation, -1..1
//   m.inPk, m.outPk             linear mono peaks of the frame
//   m.specIn[48], m.specOut[48] band levels, dBFS, 20 Hz .. 20 kHz, log-spaced (bandHz(i) = centre)
//   m.xfer[32]                  mean output per input-amplitude bin (-1..1 in 32 bins); -9 = no data
//   m.scopeL[64], m.scopeR[64]  recent output samples (about 5 ms)
//   m.inScopeL[64], m.inScopeR[64] the same input samples
//   m.ms[4]                     RMS dBFS of input mid, input side, output mid, output side
//   m.specDiff[48]              band levels of (output - input), dBFS: what the effect added/removed
//   m.diffRmsDb, m.dcOut        level of (output - input) in dBFS; output DC offset (linear)
//   m.xcorr[64]                 |cross-correlation| of output vs input for lags 0..2047 samples
//                               (bin b = lags 32b..32b+31, ~0.67 ms per bin at 48 kHz); a pure
//                               delay of d samples peaks in bin d/32 (echo taps, pre-delay)
// A design option may define live(st, m, dt) to fill the state its draw() reads; otherwise
// liveGeneric fills inL / outL / gr / hist.
function measureFromFrame(f) {
  const l = f.levels, s = f.scope || [];
  return { inPkDb: [l[0], l[1]], outPkDb: [l[2], l[3]], inRmsDb: l[4], outRmsDb: l[5], gainDb: l[6], corr: l[7],
           inPk: f.peaks[0], outPk: f.peaks[1], specIn: f.spec_in, specOut: f.spec_out, xfer: f.xfer,
           scopeL: s.slice(0, 64), scopeR: s.slice(64),
           inScopeL: (f.scope_in || []).slice(0, 64), inScopeR: (f.scope_in || []).slice(64),
           ms: f.ms || [-120, -120, -120, -120], specDiff: f.spec_diff || [],
           diffRmsDb: f.diff ? f.diff[0] : -120, dcOut: f.diff ? f.diff[1] : 0, xcorr: f.xcorr || [] };
}
function bandHz(i) { return 20 * Math.pow(1000, (i + 0.5) / 48); }

// Generic mapping for designs without their own live(): level, gain change and history.
function liveGeneric(st, m, dt) {
  const inDb = Math.max(m.inPkDb[0], m.inPkDb[1]), outDb = Math.max(m.outPkDb[0], m.outPkDb[1]);
  st.inL = Math.max(inDb, (st.inL === undefined ? -60 : st.inL) - 24 * dt);
  st.outL = Math.max(outDb, (st.outL === undefined ? -60 : st.outL) - 24 * dt);
  const grNow = Math.max(0, -m.gainDb);
  st.gr = (st.gr || 0) + (grNow - (st.gr || 0)) * (grNow > (st.gr || 0) ? 0.6 : 0.15);
  st.hist = st.hist || [];
  st.hist.push({ inA: m.inPk, out: outDb, gr: st.gr, dry: m.inPk, wet: m.outPk });
  if (st.hist.length > 800) st.hist.shift();
}

// ---------------------------------------------------------------- displays
function grNeedle(c, th, x, y, w, h, gr) {
  rr(c, x, y, w, h, 3, th.display);
  // pivot below the display, as in Glue Compressor: 0 dB at upper-left, 20 dB at right
  const cx = x + w * 0.42, cy = y + h + 14, R = h + 2;
  const ang = g => -Math.PI * 0.83 + (g / 20) * Math.PI * 0.58;
  c.save(); c.beginPath(); c.rect(x, y, w, h); c.clip();
  [0, 5, 10, 15, 20].forEach(g => {
    const a = ang(g), co = Math.cos(a), si = Math.sin(a);
    c.strokeStyle = th.scale; c.lineWidth = 2;
    c.beginPath(); c.moveTo(cx + co * (R - 12), cy + si * (R - 12)); c.lineTo(cx + co * (R - 5), cy + si * (R - 5)); c.stroke();
    txt(c, cx + co * (R - 21), cy + si * (R - 21) + 3, String(g), { color: th.dispText, size: 10 });
  });
  const a = ang(Math.min(20, gr));
  c.strokeStyle = th.cyan; c.lineWidth = 2;
  c.beginPath(); c.moveTo(cx, cy); c.lineTo(cx + Math.cos(a) * (R - 3), cy + Math.sin(a) * (R - 3)); c.stroke();
  c.restore();
  txt(c, x + w - 6, y + 12, "GR dB", { color: th.scale, size: 9, align: "right" });
}
// the simulated compressor has a known threshold (-14 dB); real effects do not report one
function st_thr(hist) { return hist.simThr ? -14 : null; }
function activity(c, th, x, y, w, h, hist) {
  rr(c, x, y, w, h, 3, th.display);
  c.save(); c.beginPath(); c.rect(x, y, w, h); c.clip();
  const n = Math.min(hist.length, w), base = y + h;
  const toY = dbv => y + 8 + (h - 16) * (-dbv / 40);
  // input waveform (grey, filled from the bottom)
  c.fillStyle = S.theme === "light" ? "#5e5e5e" : "#3a3a3a"; c.beginPath(); c.moveTo(x + w, base);
  for (let i = 0; i < n; i++) { const e = hist[hist.length - 1 - i]; c.lineTo(x + w - i, toY(db(e.inA * 0.9 + 0.02))); }
  c.lineTo(x + w - n, base); c.fill();
  // threshold line
  if (st_thr(hist) !== null) { c.strokeStyle = th.cyan; c.lineWidth = 1.5; c.beginPath(); c.moveTo(x, toY(-14)); c.lineTo(x + w, toY(-14)); c.stroke(); }
  // gain reduction trace (orange, from the top)
  c.strokeStyle = th.orange; c.lineWidth = 1.5; c.beginPath();
  for (let i = 0; i < n; i++) { const e = hist[hist.length - 1 - i]; const yy = y + 6 + e.gr * 3; i ? c.lineTo(x + w - i, yy) : c.moveTo(x + w - i, yy); }
  c.stroke();
  c.restore();
}
function limiterMeters(c, th, x, y, w, h, st) {
  rr(c, x, y, w, h, 3, th.display);
  const scale = [0, 3, 6, 12, 24], top = y + 18, mh = h - 34;
  const toFrac = dbv => 1 - Math.min(1, Math.max(0, -dbv / 24) ** 0.6);
  const toY = dbv => top + mh * (1 - toFrac(dbv));
  txt(c, x + 28, y + 12, "In", { color: th.dispText }); txt(c, x + w - 28, y + 12, "GR", { color: th.dispText });
  const inV = toFrac(st.inL + 4);
  meterV(c, th, x + 12, top, 9, mh, inV); meterV(c, th, x + 23, top, 9, mh, inV * 0.97);
  scale.forEach(s => { const yy = toY(-s); txt(c, x + w / 2, yy + 3, String(s), { color: th.dispText, size: 9 });
    c.fillStyle = th.scale; c.fillRect(x + 38, yy, 5, 1); c.fillRect(x + w - 43, yy, 5, 1); });
  const grF = Math.min(1, st.gr / 12);
  meterV(c, th, x + w - 32, top, 9, mh, grF, true, th.orange); meterV(c, th, x + w - 21, top, 9, mh, grF, true, th.orange);
  txt(c, x + 28, y + h - 5, `${Math.max(-60, st.inL).toFixed(1)}`, { color: th.cyan, size: 9.5 });
  txt(c, x + w - 26, y + h - 5, `-${st.gr.toFixed(1)}`, { color: th.orange, size: 9.5 });
}
function waveScroll(c, th, x, y, w, h, hist, key, color) {
  c.save(); c.beginPath(); c.rect(x, y, w, h); c.clip();
  const mid = y + h / 2, n = Math.min(hist.length, w);
  c.fillStyle = color; c.beginPath(); c.moveTo(x + w, mid);
  for (let i = 0; i < n; i++) c.lineTo(x + w - i, mid - hist[hist.length - 1 - i][key] * h * 0.46);
  for (let i = n - 1; i >= 0; i--) c.lineTo(x + w - i, mid + hist[hist.length - 1 - i][key] * h * 0.46 * (0.7 + 0.3 * Math.abs(noise(i))));
  c.fill(); c.restore();
}
// Decay display. With real measurements (st.envHist: output RMS dB at ~30 Hz, newest last) it
// draws the last 3 s of output level and estimates the decay time as 3 x the time the level
// takes to fall 20 dB after its loudest point; otherwise it draws a simulated tail.
function decayMap(c, th, x, y, w, h, st) {
  rr(c, x, y, w, h, 3, th.display);
  c.save(); c.beginPath(); c.rect(x, y, w, h); c.clip();
  c.strokeStyle = th.dline; c.lineWidth = 1;
  for (let i = 1; i < 4; i++) { const yy = y + 14 + (h - 30) * i / 4; c.beginPath(); c.moveTo(x, yy); c.lineTo(x + w, yy); c.stroke(); }
  c.fillStyle = th.cyan + "44"; c.strokeStyle = th.cyan; c.lineWidth = 1.5; c.beginPath();
  c.moveTo(x + 6, y + h - 14);
  let label;
  if (st.envHist && st.envHist.length > 2) {
    const e = st.envHist, n = e.length, span = 90;
    const fy = d => y + h - 14 - (h - 30) * Math.max(0, Math.min(1, 1 + d / 60));
    for (let i = 0; i < n; i++) c.lineTo(x + 6 + (w - 12) * (i + span - n) / (span - 1), fy(e[i]));
    c.lineTo(x + w - 6, y + h - 14); c.fill(); c.stroke();
    let pk = 0;
    for (let i = 1; i < n; i++) if (e[i] > e[pk]) pk = i;
    let k = pk;
    while (k < n && e[k] > e[pk] - 20) k++;
    label = k < n ? `≈ ${(3 * (k - pk) / 30).toFixed(2)} s` : "> 3 s";
  } else {
    const t60 = 1.9;
    for (let i = 0; i <= w - 12; i++) {
      const tt = (i / (w - 12)) * 3;
      let e = Math.exp(-tt * 6.9 / t60);
      if (tt < 0.08) e *= tt / 0.08;
      const er = tt < 0.12 ? 0.25 * Math.abs(noise(i * 3)) : 0;
      c.lineTo(x + 6 + i, y + h - 14 - (h - 30) * Math.min(1, e + er));
    }
    c.lineTo(x + w - 6, y + h - 14); c.fill(); c.stroke();
    const px = x + 6 + (w - 12) * ((st.t % 1) / 1);
    c.strokeStyle = th.orange; c.beginPath(); c.moveTo(px, y + 14); c.lineTo(px, y + h - 14); c.stroke();
    label = `≈ ${t60.toFixed(2)} s`;
  }
  c.restore();
  txt(c, x + 6, y + 11, "Decay", { color: th.scale, align: "left" });
  txt(c, x + w - 6, y + 11, label, { color: th.orange, align: "right" });
  const ticks = st.envHist ? ["-3 s", "-2 s", "-1 s", "now"] : ["0", "1 s", "2 s", "3 s"];
  ticks.forEach((s, i) => txt(c, x + 6 + (w - 12) * i / 3, y + h - 3, s, { color: th.scale, size: 8.5, align: i ? (i === 3 ? "right" : "center") : "left" }));
}
// A control shown as a draggable number (like Hybrid Reverb's display row). In the device an
// invisible live.dial lies over it, so it drags like a dial and stays automatable.
function readout(c, th, x, y, w, p, v) {
  hint(x, y - 11, w, 28, p.name, p.info || `A control of ${S.effName || "this effect"}. Drag up or down to change it.`);
  txt(c, x + w / 2, y, p.name, { color: th.dispText, size: 10 });
  txt(c, x + w / 2, y + 15, fmt(p.display), { color: th.cyan, size: 11 });
}

// Colour key in one style for every device: small swatches with labels, left to right.
// items: [[colour, label, explanation], ...]. Each item also gets a hover hint. Returns end x.
function legend(c, th, x, y, items, o = {}) {
  const size = o.size || 8.5;
  c.font = `400 ${size}px ${FONT}`;
  let cx = x;
  for (const [col, label, info] of items) {
    const tw = Math.ceil(c.measureText(label).width);
    c.fillStyle = col;
    if (o.line) c.fillRect(cx, y - 4, 8, 2); else c.fillRect(cx, y - 6, 6, 6);
    txt(c, cx + (o.line ? 11 : 9), y, label, { color: o.color || th.dispText, align: "left", size });
    if (info) hint(cx - 1, y - 9, tw + 12, 12, label, info);
    cx += tw + (o.line ? 11 : 9) + (o.gap || 8);
  }
  return cx;
}

// Several options of one category in one device, switched by the View selector at the top of
// the Input/Output column, like the display buttons of Live's Compressor. Each view keeps its
// own state (and history), so switching is instant. Narrower views are centred.
function composeViews(des, ids) {
  const opts = ids.map(id => des.options.find(o => o.id === id)).filter(Boolean);
  const W = Math.max(...opts.map(o => o.width));
  const labels = opts.map(o => o.short || o.name.split(/[ (—]/)[0]);
  const sub = st => (st.sub = st.sub || opts.map(() => newState()));
  return {
    id: opts.map(o => o.id).join("+"), name: opts.map(o => o.name).join(" / "), width: W, views: labels,
    why: "Views: " + opts.map((o, i) => `${labels[i]} — ${o.why}`).join(" "),
    bullets: ["Click a View button (top of the Input/Output column) to switch the display"].concat(opts.map((o, i) => `${labels[i]}: ${o.bullets[0]}`)),
    step(st, dt) { sub(st).forEach((s, i) => { s.t = st.t; opts[i].step(s, dt); }); },
    live(st, m, dt) { sub(st).forEach((s, i) => { s.t = st.t; (opts[i].live || liveGeneric)(s, m, dt); }); },
    click(x, y, st) {
      for (const [i, r] of (st.viewRects || []).entries())
        if (x >= r.x && x <= r.x + r.w && y >= r.y && y <= r.y + r.h) { st.view = i; return; }
      const v = Math.min(st.view || 0, opts.length - 1);
      if (opts[v].click) opts[v].click(x - (st.dx || 0), y, sub(st)[v]);
    },
    draw(c, th, st, ps, vals) {
      const v = Math.min(st.view || 0, opts.length - 1), o = opts[v];
      const dx = Math.round((W - o.width) / 2);
      st.dx = dx;
      c.save(); c.translate(dx, 0);
      S.offX = dx; S.gainX = W - GAIN_W - 4; S.views = { labels, active: v };
      try { o.draw(c, th, sub(st)[v], ps, vals); }
      finally { st.viewRects = S.viewRects; c.restore(); S.offX = 0; S.gainX = undefined; S.views = null; }
    },
  };
}

// Word-wrapped text block (e.g. the effect description) inside width w, at most maxLines.
function wrapText(c, x, y, w, text, o = {}) {
  c.font = `400 ${o.size || 9.5}px ${FONT}`;
  const words = String(text || "").split(/\s+/).filter(Boolean), lines = [];
  let line = "";
  for (const wd of words) {
    const t = line ? line + " " + wd : wd;
    if (c.measureText(t).width > w && line) { lines.push(line); line = wd; } else line = t;
  }
  if (line) lines.push(line);
  lines.slice(0, o.maxLines || 6).forEach((l, i) => txt(c, x, y + i * (o.lh || 12), l, { color: o.color, align: "left", size: o.size }));
}

// Standard Input / Output gain strip, required on every device (user decision 2026-10-23).
// Two dB dials (Input above, Output below) and a stereo In / Out meter pair. Width GAIN_W.
const GAIN_W = 64;
function gainStrip(c, th, x, st) {
  if (S.gainX !== undefined) x = S.gainX - S.offX;    // several views: always at the right edge
  const y = HEAD_H + 6, h = DEVICE_H - 12;
  rr(c, x, y, GAIN_W, h, 3, th.panel);
  let top = y;
  if (S.views) {                                      // view selector at the top of the column
    viewTabsV(c, th, x + 3, y + 3, GAIN_W - 6, S.views.labels, S.views.active);
    top = y + 3 + S.views.labels.length * 15 + 1;
  }
  const dbTxt = v => (v > 0 ? "+" : "") + v.toFixed(1) + " dB";
  const room = y + h - top, kh = Math.min(room / 2, 78);
  knob(c, th, x - 2, top + Math.max(2, (kh - 50) / 2), 44, { name: "Input", display: dbTxt(st.inGain || 0),
    info: "Input gain in dB, applied before the effect. Drives the effect harder or softer; the left meter pair shows the level after it." }, 0.5 + (st.inGain || 0) / 72);
  knob(c, th, x - 2, top + kh + Math.max(0, (kh - 50) / 2), 44, { name: "Output", display: dbTxt(st.outGain || 0),
    info: "Output gain in dB, applied after the effect. The right meter pair shows the level after it." }, 0.5 + (st.outGain || 0) / 72);
  const f = dbv => Math.max(0, 1 + (Number.isFinite(dbv) ? dbv : -60) / 48);
  const mx = x + 44, mt = top + 1, mh = y + h - 4 - mt;
  meterV(c, th, mx, mt, 3, mh, f(st.inL)); meterV(c, th, mx + 4, mt, 3, mh, f(st.inL) * 0.96);
  meterV(c, th, mx + 10, mt, 3, mh, f(st.outL)); meterV(c, th, mx + 14, mt, 3, mh, f(st.outL) * 0.97);
  hint(mx, mt, 18, mh, "In / Out Meters", "Left pair: input level after the Input gain. Right pair: output level after the Output gain. Scale 0 dB (top) to -48 dB.");
}

// Vertical view selector (several views in one device). Rects go to S.viewRects for clicks.
function viewTabsV(c, th, x, y, w, labels, active) {
  S.viewRects = labels.map((l, i) => {
    toggle(c, th, x, y + i * 15, w, l, i === active);
    return { x: x + S.offX, y: y + i * 15, w, h: 14 };
  });
  hint(x, y, w, labels.length * 15, "View", `Chooses what the display shows: ${labels.join(", ")}. The controls and the sound do not change.`);
}

function viewTabs(c, th, x, y, labels, active) {
  let cx = x;
  hint(x, y, labels.length * 60, 15, "View", `Chooses what the display shows: ${labels.join(", ")}.`);
  return labels.map((l, i) => {
    c.font = `400 9.5px ${FONT}`;
    const w = Math.ceil(c.measureText(l).width) + 12;
    toggle(c, th, cx, y, w, l, i === active);
    const r = { x: cx, y, w, h: 14 };
    cx += w + 2;
    return r;
  });
}

function ioMeters(c, th, x, y, h, st) {
  const f = dbv => Math.max(0, 1 + dbv / 48);
  meterV(c, th, x, y, 4, h, f(st.inL)); meterV(c, th, x + 5, y, 4, h, f(st.inL) * 0.96);
  meterV(c, th, x + 13, y, 4, h, f(st.outL)); meterV(c, th, x + 18, y, 4, h, f(st.outL) * 0.97);
  txt(c, x + 4.5, y + h + 10, "In", { color: th.text, size: 8.5 }); txt(c, x + 17.5, y + h + 10, "Out", { color: th.text, size: 8.5 });
}

// ---------------------------------------------------------------- options per category
// Each category registers its options in designs/<Category>.js
const DESIGNS = {};


// mgcanvas.js : a small HTML-canvas 2D context on top of Max's mgraphics.
//
// The review page draws device UIs with the canvas API. In Max the same code runs in a
// v8ui, through this adapter, so what was approved in the browser is what the device shows.
//
// mgraphics has no clip, so the adapter flattens every path to polylines (arcs and rounded
// rectangles become short segments), applies its own transform, clips to the current clip
// rectangle (Sutherland–Hodgman for fills, Liang–Barsky for strokes), then emits plain
// move_to / line_to. Text is dropped when its anchor is outside the clip rectangle.
//
//   const c = makeCanvas(mgraphics, { font: "Ableton Sans Medium", boldFont: "Ableton Sans Bold" });
//   c.fillStyle = "#ffad56"; c.fillRect(0, 0, 10, 10);

function makeCanvas(mg, opts) {
  opts = opts || {};
  const FONT_REG = opts.font || "Ableton Sans Medium";
  const FONT_BOLD = opts.boldFont || "Ableton Sans Bold";

  // ---------------------------------------------------------------- colour
  const named = { black: [0, 0, 0, 1], white: [1, 1, 1, 1], transparent: [0, 0, 0, 0] };
  const cache = {};
  function parseColor(s) {
    if (s && typeof s === "object" && s._stops) s = s._stops.length ? s._stops[0][1] : "#000"; // gradient: first stop
    s = String(s || "#000").trim();
    if (cache[s]) return cache[s];
    let c = named[s];
    if (!c && s[0] === "#") {
      let h = s.slice(1);
      if (h.length === 3 || h.length === 4) h = h.split("").map(x => x + x).join("");
      const n = i => parseInt(h.slice(i, i + 2), 16) / 255;
      c = [n(0), n(2), n(4), h.length >= 8 ? n(6) : 1];
    }
    if (!c) {
      const m = s.match(/rgba?\(([^)]+)\)/);
      if (m) {
        const p = m[1].split(/[ ,/]+/).filter(Boolean).map(parseFloat);
        c = [p[0] / 255, p[1] / 255, p[2] / 255, p.length > 3 ? p[3] : 1];
      }
    }
    return (cache[s] = c || [0, 0, 0, 1]);
  }

  // ---------------------------------------------------------------- transform
  let M = [1, 0, 0, 1, 0, 0]; // a b c d e f
  const tx = (x, y) => [M[0] * x + M[2] * y + M[4], M[1] * x + M[3] * y + M[5]];
  const scaleOf = () => Math.sqrt(Math.abs(M[0] * M[3] - M[1] * M[2])) || 1;
  function mul(a, b, c, d, e, f) {
    M = [M[0] * a + M[2] * b, M[1] * a + M[3] * b, M[0] * c + M[2] * d, M[1] * c + M[3] * d,
         M[0] * e + M[2] * f + M[4], M[1] * e + M[3] * f + M[5]];
  }

  // ---------------------------------------------------------------- path (device coords)
  let subs = [];   // [{pts: [[x,y],...], closed}]
  let cur = null;
  const startAt = (x, y) => { cur = { pts: [tx(x, y)], closed: false }; subs.push(cur); };
  const add = (x, y) => { if (!cur) startAt(x, y); else cur.pts.push(tx(x, y)); };

  function arcPts(x, y, r, a0, a1, ccw) {
    let sweep = a1 - a0;
    if (!ccw && sweep < 0) sweep = (sweep % (2 * Math.PI)) + 2 * Math.PI;
    if (ccw && sweep > 0) sweep = (sweep % (2 * Math.PI)) - 2 * Math.PI;
    if (Math.abs(a1 - a0) >= 2 * Math.PI) sweep = ccw ? -2 * Math.PI : 2 * Math.PI;
    const n = Math.max(4, Math.ceil(Math.abs(sweep) * Math.max(r * scaleOf(), 1) / 3));
    for (let i = 0; i <= n; i++) {
      const a = a0 + sweep * i / n;
      add(x + Math.cos(a) * r, y + Math.sin(a) * r);
    }
  }

  // ---------------------------------------------------------------- clipping
  let clipR = null; // [x0, y0, x1, y1] device coords
  const stack = [];

  function clipPoly(pts) {
    if (!clipR) return pts;
    const [x0, y0, x1, y1] = clipR;
    const edges = [
      [p => p[0] >= x0, (a, b) => [x0, a[1] + (b[1] - a[1]) * (x0 - a[0]) / (b[0] - a[0])]],
      [p => p[0] <= x1, (a, b) => [x1, a[1] + (b[1] - a[1]) * (x1 - a[0]) / (b[0] - a[0])]],
      [p => p[1] >= y0, (a, b) => [a[0] + (b[0] - a[0]) * (y0 - a[1]) / (b[1] - a[1]), y0]],
      [p => p[1] <= y1, (a, b) => [a[0] + (b[0] - a[0]) * (y1 - a[1]) / (b[1] - a[1]), y1]],
    ];
    let out = pts;
    for (const [inside, cut] of edges) {
      const inp = out; out = [];
      for (let i = 0; i < inp.length; i++) {
        const a = inp[(i + inp.length - 1) % inp.length], b = inp[i];
        if (inside(b)) { if (!inside(a)) out.push(cut(a, b)); out.push(b); }
        else if (inside(a)) out.push(cut(a, b));
      }
      if (!out.length) break;
    }
    return out;
  }
  function clipSeg(a, b) {
    if (!clipR) return [a, b];
    const [x0, y0, x1, y1] = clipR;
    let t0 = 0, t1 = 1;
    const dx = b[0] - a[0], dy = b[1] - a[1];
    for (const [p, q] of [[-dx, a[0] - x0], [dx, x1 - a[0]], [-dy, a[1] - y0], [dy, y1 - a[1]]]) {
      if (p === 0) { if (q < 0) return null; continue; }
      const r = q / p;
      if (p < 0) { if (r > t1) return null; if (r > t0) t0 = r; }
      else { if (r < t0) return null; if (r < t1) t1 = r; }
    }
    return [[a[0] + t0 * dx, a[1] + t0 * dy], [a[0] + t1 * dx, a[1] + t1 * dy]];
  }

  // ---------------------------------------------------------------- emit
  let alpha = 1;
  function source(style) {
    const c = parseColor(style);
    mg.set_source_rgba(c[0], c[1], c[2], c[3] * alpha);
    return c[3] * alpha > 0;
  }
  function emitFill() {
    mg.new_path();
    let any = false;
    for (const s of subs) {
      if (s.pts.length < 3) continue;
      const p = clipPoly(s.pts);
      if (p.length < 3) continue;
      mg.move_to(p[0][0], p[0][1]);
      for (let i = 1; i < p.length; i++) mg.line_to(p[i][0], p[i][1]);
      mg.close_path();
      any = true;
    }
    if (any) mg.fill(); else mg.new_path();
  }
  function emitStroke(lineWidth) {
    mg.new_path();
    mg.set_line_width(Math.max(0.1, lineWidth * scaleOf()));
    let any = false;
    for (const s of subs) {
      const pts = s.closed && s.pts.length > 2 ? s.pts.concat([s.pts[0]]) : s.pts;
      let open = false, last = null;
      for (let i = 1; i < pts.length; i++) {
        const seg = clipSeg(pts[i - 1], pts[i]);
        if (!seg) { open = false; continue; }
        const [a, b] = seg;
        if (!open || !last || Math.abs(last[0] - a[0]) > 1e-6 || Math.abs(last[1] - a[1]) > 1e-6) mg.move_to(a[0], a[1]);
        mg.line_to(b[0], b[1]);
        last = b; open = true; any = true;
      }
    }
    if (any) mg.stroke(); else mg.new_path();
  }

  // ---------------------------------------------------------------- font
  let fontKey = "";
  function applyFont(font) {
    if (font === fontKey) return;
    fontKey = font;
    const m = String(font).match(/(\d+)?\s*([\d.]+)px/);
    const bold = /\b(700|bold)\b/.test(font);
    mg.select_font_face(bold ? FONT_BOLD : FONT_REG);
    mg.set_font_size((m ? parseFloat(m[2]) : 10) * scaleOf());
  }

  // ---------------------------------------------------------------- the context
  const ctx = {
    fillStyle: "#000", strokeStyle: "#000", lineWidth: 1, lineCap: "butt", lineJoin: "miter",
    font: "10px sans-serif", textAlign: "start", textBaseline: "alphabetic",
    get globalAlpha() { return alpha; }, set globalAlpha(v) { alpha = Math.max(0, Math.min(1, +v)); },

    save() { stack.push({ M: M.slice(), clipR: clipR && clipR.slice(), alpha, fillStyle: ctx.fillStyle, strokeStyle: ctx.strokeStyle,
                          lineWidth: ctx.lineWidth, font: ctx.font, textAlign: ctx.textAlign, textBaseline: ctx.textBaseline, lineCap: ctx.lineCap }); },
    restore() {
      const s = stack.pop(); if (!s) return;
      M = s.M; clipR = s.clipR; alpha = s.alpha;
      Object.assign(ctx, { fillStyle: s.fillStyle, strokeStyle: s.strokeStyle, lineWidth: s.lineWidth, font: s.font, textAlign: s.textAlign, textBaseline: s.textBaseline, lineCap: s.lineCap });
    },
    setTransform(a, b, c, d, e, f) { M = [a, b, c, d, e, f]; },
    resetTransform() { M = [1, 0, 0, 1, 0, 0]; },
    translate(x, y) { mul(1, 0, 0, 1, x, y); },
    scale(x, y) { mul(x, 0, 0, y, 0, 0); },
    rotate(a) { const c = Math.cos(a), s = Math.sin(a); mul(c, s, -s, c, 0, 0); },

    beginPath() { subs = []; cur = null; },
    moveTo(x, y) { startAt(x, y); },
    lineTo(x, y) { add(x, y); },
    closePath() { if (cur) { cur.closed = true; const p = cur.pts[0]; cur = { pts: [p], closed: false }; subs.push(cur); } },
    rect(x, y, w, h) { startAt(x, y); add(x + w, y); add(x + w, y + h); add(x, y + h); cur.closed = true; cur = null; },
    roundRect(x, y, w, h, r) {
      r = Math.max(0, Math.min(Array.isArray(r) ? r[0] : (r || 0), Math.abs(w) / 2, Math.abs(h) / 2));
      if (!r) return ctx.rect(x, y, w, h);
      cur = null;
      arcPts(x + w - r, y + r, r, -Math.PI / 2, 0);
      arcPts(x + w - r, y + h - r, r, 0, Math.PI / 2);
      arcPts(x + r, y + h - r, r, Math.PI / 2, Math.PI);
      arcPts(x + r, y + r, r, Math.PI, Math.PI * 1.5);
      cur.closed = true; cur = null;
    },
    arc(x, y, r, a0, a1, ccw) { arcPts(x, y, r, a0, a1, !!ccw); },
    ellipse(x, y, rx, ry, rot, a0, a1, ccw) { ctx.save(); ctx.translate(x, y); ctx.rotate(rot || 0); ctx.scale(rx, ry); arcPts(0, 0, 1, a0, a1, !!ccw); ctx.restore(); },
    quadraticCurveTo(cx, cy, x, y) {
      const p0 = cur ? cur.pts[cur.pts.length - 1] : tx(cx, cy);
      // p0 is in device coords; sample the curve in user coords via inverse-free approach:
      const inv = invPoint(p0[0], p0[1]);
      for (let i = 1; i <= 12; i++) { const t = i / 12, u = 1 - t; add(u * u * inv[0] + 2 * u * t * cx + t * t * x, u * u * inv[1] + 2 * u * t * cy + t * t * y); }
    },
    bezierCurveTo(c1x, c1y, c2x, c2y, x, y) {
      const p0 = cur ? cur.pts[cur.pts.length - 1] : tx(c1x, c1y);
      const inv = invPoint(p0[0], p0[1]);
      for (let i = 1; i <= 16; i++) {
        const t = i / 16, u = 1 - t;
        add(u * u * u * inv[0] + 3 * u * u * t * c1x + 3 * u * t * t * c2x + t * t * t * x,
            u * u * u * inv[1] + 3 * u * u * t * c1y + 3 * u * t * t * c2y + t * t * t * y);
      }
    },
    fill() { if (source(ctx.fillStyle)) emitFill(); },
    stroke() { if (source(ctx.strokeStyle)) emitStroke(ctx.lineWidth); },
    clip() {
      // only rectangles are needed by the designs: clip to the bounding box of the path
      let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
      for (const s of subs) for (const [x, y] of s.pts) { x0 = Math.min(x0, x); y0 = Math.min(y0, y); x1 = Math.max(x1, x); y1 = Math.max(y1, y); }
      if (!Number.isFinite(x0)) return;
      clipR = clipR ? [Math.max(clipR[0], x0), Math.max(clipR[1], y0), Math.min(clipR[2], x1), Math.min(clipR[3], y1)] : [x0, y0, x1, y1];
    },
    fillRect(x, y, w, h) { const keep = subs; ctx.beginPath(); ctx.rect(x, y, w, h); ctx.fill(); subs = keep; cur = null; },
    strokeRect(x, y, w, h) { const keep = subs; ctx.beginPath(); ctx.rect(x, y, w, h); ctx.stroke(); subs = keep; cur = null; },
    clearRect() {},
    setLineDash() {}, getLineDash() { return []; },
    createLinearGradient() { return { _stops: [], addColorStop(o, c) { this._stops.push([o, c]); } }; },
    createRadialGradient() { return { _stops: [], addColorStop(o, c) { this._stops.push([o, c]); } }; },

    measureText(s) {
      applyFont(ctx.font);
      const m = mg.text_measure(String(s));
      return { width: m[0] / scaleOf() };
    },
    fillText(s, x, y) {
      s = String(s);
      if (!source(ctx.fillStyle)) return;
      applyFont(ctx.font);
      const m = mg.text_measure(s), sc = scaleOf();
      let [dx, dy] = tx(x, y);
      const a = ctx.textAlign;
      if (a === "center") dx -= m[0] / 2; else if (a === "right" || a === "end") dx -= m[0];
      // mgraphics show_text draws from the baseline; approximate other baselines
      const size = m[1];
      const b = ctx.textBaseline;
      if (b === "middle") dy += size * 0.35; else if (b === "top" || b === "hanging") dy += size * 0.75; else if (b === "bottom") dy -= size * 0.2;
      if (clipR && (dx + m[0] < clipR[0] || dx > clipR[2] || dy < clipR[1] || dy - size * 0.7 > clipR[3])) return;
      mg.move_to(dx, dy);
      mg.show_text(s);
      mg.new_path();
      void sc;
    },
    strokeText(s, x, y) { const f = ctx.fillStyle; ctx.fillStyle = ctx.strokeStyle; ctx.fillText(s, x, y); ctx.fillStyle = f; },
  };

  function invPoint(x, y) {
    const det = M[0] * M[3] - M[1] * M[2] || 1;
    const X = x - M[4], Y = y - M[5];
    return [(M[3] * X - M[2] * Y) / det, (-M[1] * X + M[0] * Y) / det];
  }

  return ctx;
}



// Dithers: design options. All helpers are private to this IIFE.
(() => {
  const N = 256, K = 128;
  const WIN = Array.from({ length: N }, (_, i) => 0.5 - 0.5 * Math.cos(2 * Math.PI * i / (N - 1)));
  const COS = [], SIN = [];
  for (let k = 0; k < K; k++) { COS.push(new Float32Array(N)); SIN.push(new Float32Array(N));
    for (let n = 0; n < N; n++) { COS[k][n] = Math.cos(2 * Math.PI * k * n / N); SIN[k][n] = Math.sin(2 * Math.PI * k * n / N); } }

  // Simulated 16-bit quantiser with TPDF dither and a little noise shaping.
  // Measures in-vs-out: error = out - in, its spectrum, histogram and level.
  const dbl = a => 20 * Math.log10(Math.max(a, 1e-9));
  function step0(st, dt) {
    if (!st.dz) Object.assign(st, { dz: true, n: 0, cnt: 1, s: new Float32Array(N), y: new Float32Array(N), e: new Float32Array(N),
      spec: new Float32Array(K).fill(-130), hist: new Float32Array(31), nd: -98, ndL: -98, ndR: -98, snr: 60, amp: 3, nh: [], peak: 0, floor: -110 });
    const amp = 3 + 1.8 * Math.sin(st.t * 0.6), shape = 0.75 + 0.2 * Math.sin(st.t * 0.45 + 1), ph = st.t * 3;
    let eq = 0, sq = 0, sqL = 0, sqR = 0, pk = 0;
    for (let n = 0; n < N; n++) {
      const s = amp * Math.sin(2 * Math.PI * 4 * n / N + ph);
      const r = (noise(st.cnt++) + noise(st.cnt++)) * 0.5 * 1.0;
      const v = s - shape * eq, y = Math.round(v + r);
      eq = y - v; st.s[n] = s; st.y[n] = y; st.e[n] = y - s;
      sq += st.e[n] ** 2; if (n < N / 2) sqL += st.e[n] ** 2; else sqR += st.e[n] ** 2;
      pk = Math.max(pk, Math.abs(st.e[n]));
      const b = Math.round(st.e[n] / 0.2) + 15; if (b >= 0 && b < 31) st.hist[b] += 1;
    }
    for (let b = 0; b < 31; b++) st.hist[b] *= 0.985;
    const f = dbv => dbv;
    st.nd += (f(dbl(Math.sqrt(sq / N) / 32768)) - st.nd) * 0.2;
    st.ndL += (dbl(Math.sqrt(sqL / (N / 2)) / 32768) - st.ndL) * 0.2;
    st.ndR += (dbl(Math.sqrt(sqR / (N / 2)) / 32768) - st.ndR) * 0.2;
    st.snr += (dbl((amp / Math.SQRT2) / Math.max(1e-3, Math.sqrt(sq / N))) - st.snr) * 0.2;
    st.peak = Math.max(pk, st.peak - dt * 1.5); st.amp = amp;
    st.nh.push(st.nd); if (st.nh.length > 600) st.nh.shift();
    if (++st.n % 2 === 0) {                      // spectrum of the output (tone + noise floor)
      let sum = 0;
      for (let k = 0; k < K; k++) {
        let re = 0, im = 0;
        for (let n = 0; n < N; n++) { const w = WIN[n] * st.y[n]; re += w * COS[k][n]; im -= w * SIN[k][n]; }
        const m = Math.sqrt(re * re + im * im) * 2 / (N * 0.5) / 32768;
        st.spec[k] += (dbl(m) - st.spec[k]) * 0.35; if (k > 3) sum += st.spec[k];
      }
      st.floor = sum / (K - 4);
    }
  }

  // ---------- live(): measurements from airwin~ (about 30 per second)
  // Fields filled: inL/outL (gain strip), s/y/e (scope input/output/error), spec/dspec (48 bands),
  // hist (error histogram, 16-bit steps), nd/ndL/ndR (noise, dBFS), peak (LSB), snrTxt, lvl, nh (history).
  const NBD = 48, LSB = 32768;
  const fin = (v, d) => (Number.isFinite(v) ? v : d);
  const hold = (prev, v, rate, dt) => Math.max(v, fin(prev, -120) - rate * dt);
  const dbF = a => Math.max(-120, dbl(a));
  function live(st, m, dt) {
    if (!st.lz) Object.assign(st, { lz: true, real: true, s: [], y: [], e: [], hist: new Float32Array(31), nd: -120, ndL: -120, ndR: -120, peak: 0,
      spec: new Float32Array(NBD).fill(-120), dspec: new Float32Array(NBD).fill(-120), nh: [], lvl: -120, snrTxt: "", wsc: 0.05, inL: -60, outL: -60 });
    st.inL = hold(st.inL, Math.max(fin(m.inPkDb[0], -120), fin(m.inPkDb[1], -120)), 24, dt);
    st.outL = hold(st.outL, Math.max(fin(m.outPkDb[0], -120), fin(m.outPkDb[1], -120)), 24, dt);
    st.lvl = fin(m.outRmsDb, -120);
    st.nd = hold(st.nd, Math.max(-120, fin(m.diffRmsDb, -120)), 24, dt);
    const snr = fin(m.outRmsDb, -120) - fin(m.diffRmsDb, -120);
    st.snrTxt = st.lvl <= -119 ? "-" : m.diffRmsDb <= -119 ? ">120 dB" : `${Math.max(0, Math.min(120, snr)).toFixed(0)} dB`;
    const nS = Math.min((m.scopeL || []).length, (m.inScopeL || []).length);
    if (nS > 0) {
      st.s = Array.from(m.inScopeL.slice(0, nS), v => fin(v, 0)); st.y = Array.from(m.scopeL.slice(0, nS), v => fin(v, 0));
      st.e = st.y.map((v, i) => v - st.s[i]);
      let pkS = 0; for (let i = 0; i < nS; i++) pkS = Math.max(pkS, Math.abs(st.s[i]), Math.abs(st.y[i]));
      st.wsc = Math.max(0.01, pkS, st.wsc * Math.exp(-dt / 0.7));
      for (let b = 0; b < 31; b++) st.hist[b] *= 0.97;
      let pk = 0;
      [["scopeL", "inScopeL", "ndL"], ["scopeR", "inScopeR", "ndR"]].forEach(([o, i, k]) => {
        const a = m[o] || [], b = m[i] || [], n = Math.min(a.length, b.length, nS); let sq = 0;
        for (let j = 0; j < n; j++) { const e = fin(a[j], 0) - fin(b[j], 0); sq += e * e; pk = Math.max(pk, Math.abs(e) * LSB);
          const bin = Math.round(e * LSB / 0.2) + 15; if (bin >= 0 && bin < 31) st.hist[bin] += 1; }
        st[k] = hold(st[k], n ? dbF(Math.sqrt(sq / n)) : -120, 24, dt);
      });
      st.peak = Math.max(pk, st.peak - dt * 1.5);
    }
    for (let i = 0; i < NBD; i++) {
      st.spec[i] = hold(st.spec[i], fin((m.specOut || [])[i], -120), 30, dt);
      st.dspec[i] = hold(st.dspec[i], fin((m.specDiff || [])[i], -120), 30, dt);
    }
    st.nh.push(st.nd); if (st.nh.length > 600) st.nh.shift();
  }
  const ndTxt = st => ((st.nd === undefined || st.nd <= -119) ? "<-119 dBFS" : `${st.nd.toFixed(1)} dBFS`);
  const sameNote = (c, th, st, x, y, al, short) => { if (st.nd <= -119) txt(c, x, y, short ? "no added noise" : "output = input: no added noise", { color: th.orange, size: 9, align: al || "right" }); };
  const logX = (P, f) => P.px + P.pw * Math.log(f / bandHz(0)) / Math.log(bandHz(NBD - 1) / bandHz(0));

  // A, real: input and output scope on top, error (out - in) in 16-bit steps below
  function drawAReal(c, th, st, P) {
    const wh = Math.round(P.ph * 0.6), mid = P.py + wh / 2, sc = (wh / 2 - 3) / st.wsc, n = st.s.length;
    const ey = P.py + wh + 6, eh = P.ph - wh - 6, emid = ey + eh / 2, esc = (eh / 2 - 1) / 3;
    clipTo(c, P.px, P.py, P.pw, P.ph);
    c.lineWidth = 1; c.strokeStyle = th.scale; c.beginPath(); c.moveTo(P.px, mid); c.lineTo(P.px + P.pw, mid); c.stroke();
    c.strokeStyle = th.dline; c.beginPath(); c.moveTo(P.px, mid - wh / 2 + 3); c.lineTo(P.px + P.pw, mid - wh / 2 + 3); c.moveTo(P.px, mid + wh / 2 - 3); c.lineTo(P.px + P.pw, mid + wh / 2 - 3); c.stroke();
    if (n > 1) {
      c.strokeStyle = th.cyan; c.lineWidth = 1.5; c.beginPath();
      for (let i = 0; i < n; i++) { const x = P.px + i / (n - 1) * P.pw, y = mid - st.s[i] * sc; i ? c.lineTo(x, y) : c.moveTo(x, y); }
      c.stroke();
      c.strokeStyle = th.orange; c.lineWidth = 1.5; c.beginPath();
      for (let i = 0; i < n; i++) { const x0 = P.px + i / n * P.pw, x1 = P.px + (i + 1) / n * P.pw, y = mid - st.y[i] * sc; i ? c.lineTo(x0, y) : c.moveTo(x0, y); c.lineTo(x1, y); }
      c.stroke();
    }
    c.fillStyle = th.dline; c.fillRect(P.px, ey - 3, P.pw, 1);
    c.strokeStyle = th.dline; c.lineWidth = 1;
    for (let l = -2; l <= 2; l += 2) { c.beginPath(); c.moveTo(P.px, emid - l * esc); c.lineTo(P.px + P.pw, emid - l * esc); c.stroke(); }
    if (n > 1) {
      c.strokeStyle = th.orange; c.lineWidth = 1.5; c.beginPath();
      for (let i = 0; i < n; i++) { const x = P.px + i / (n - 1) * P.pw, y = emid - Math.max(-3, Math.min(3, st.e[i] * LSB)) * esc; i ? c.lineTo(x, y) : c.moveTo(x, y); }
      c.stroke();
    }
    c.restore();
    legend(c, th, P.x + 6, P.y + P.h - 3, [[th.cyan, "In", "The sound going into the effect, measured at its input."], [th.orange, "Out", "The sound coming out of the effect, measured at its output. In the error strip it shows out minus in."]], { line: true });
    hint(P.px, P.py, P.pw, wh, "Input And Output Waveform", "A short piece of the sound, zoomed in. Cyan is the input, orange is the output. Measured from the audio going in and out.");
    hint(P.px, ey, P.pw, eh, "Error Trace", "Output minus input, in steps of the 16-bit grid. This is the rounding noise and dither the effect adds.");
    hint(P.px + 2, P.py + 1, 120, 10, "Full Height Label", "The level that reaches the top of the scope, in dBFS. It follows the signal.");
    txt(c, P.px + 2, P.py + 9, `full height = ${dbl(st.wsc).toFixed(0)} dBFS`, { color: th.scale, size: 8.5, align: "left" });
    txt(c, P.px + 2, ey + 8, "Error (out - in), 16-bit steps", { color: th.dispText, size: 8.5, align: "left" });
    sameNote(c, th, st, P.px + P.pw - 4, ey + 8);
    txt(c, P.x + P.w - 6, P.y + P.h - 3, "grid = 2 steps", { color: th.scale, size: 8.5, align: "right" });
    hint(P.x + P.w - 70, P.y + P.h - 12, 66, 10, "Grid Size", "Each error grid line is 2 steps of the 16-bit sample. A step is the smallest level a 16-bit file can store.");
  }
  // B, real: output spectrum (cyan) with the added part (output - input) in orange
  function drawBReal(c, th, st, P) {
    const lo = -120, hi = 0, b0 = P.py + P.ph - 10, ph = P.ph - 10;
    const yOf = d => b0 - ph * (Math.min(hi, Math.max(lo, d)) - lo) / (hi - lo), xOf = i => P.px + P.pw * i / (NBD - 1);
    clipTo(c, P.px, P.py, P.pw, P.ph);
    c.lineWidth = 1; c.strokeStyle = th.dline;
    for (let d = -100; d <= -20; d += 20) { c.beginPath(); c.moveTo(P.px, yOf(d)); c.lineTo(P.px + P.pw, yOf(d)); c.stroke(); }
    c.globalAlpha = 0.28; c.fillStyle = th.cyan; c.beginPath(); c.moveTo(xOf(0), b0);
    for (let i = 0; i < NBD; i++) c.lineTo(xOf(i), yOf(st.spec[i]));
    c.lineTo(xOf(NBD - 1), b0); c.fill(); c.globalAlpha = 1;
    c.strokeStyle = th.cyan; c.lineWidth = 1.5; c.beginPath();
    for (let i = 0; i < NBD; i++) i ? c.lineTo(xOf(i), yOf(st.spec[i])) : c.moveTo(xOf(i), yOf(st.spec[i]));
    c.stroke();
    c.strokeStyle = th.orange; c.lineWidth = 1.5; c.beginPath();
    for (let i = 0; i < NBD; i++) i ? c.lineTo(xOf(i), yOf(st.dspec[i])) : c.moveTo(xOf(i), yOf(st.dspec[i]));
    c.stroke();
    c.strokeStyle = th.orange; c.lineWidth = 1; c.setLineDash && c.setLineDash([3, 3]);
    c.beginPath(); c.moveTo(P.px, yOf(st.nd)); c.lineTo(P.px + P.pw, yOf(st.nd)); c.stroke(); c.setLineDash && c.setLineDash([]);
    c.restore();
    for (let d = -100; d <= -20; d += 20) txt(c, P.px + P.pw - 2, yOf(d) - 2, String(d), { color: th.scale, size: 8.5, align: "right" });
    [[100, "100"], [1000, "1k"], [10000, "10k"]].forEach(([f, s]) => txt(c, logX(P, f), P.py + P.ph - 1, s, { color: th.scale, size: 8.5 }));
    legend(c, th, P.lx, P.ly, [[th.cyan, "Output", "The loudness of the output at each pitch (frequency). Measured from the output audio."], [th.orange, "Added", "Output minus input: the part the effect adds, at each pitch."]], { line: true });
    hint(P.px, P.py, P.pw, P.ph, "Output Spectrum", "Loudness at each pitch, low pitches on the left. Cyan is the output, orange is what the effect added. Measured from the input and output audio.");
    hint(P.px, yOf(st.nd) - 3, P.pw, 6, "Noise Floor Line", "The dashed orange line is the average level of the added noise, in dB. Measured as output minus input.");
    hint(P.px + P.pw - 24, P.py, 24, P.ph - 10, "Level Scale", "Loudness in dB. 0 dB is the loudest level a digital signal can have.");
    hint(P.px, P.py + P.ph - 10, P.pw, 10, "Pitch Scale", "Pitch in Hz, on a log scale: each step to the right is a multiple of the last.");
    sameNote(c, th, st, P.px + 3, P.py + 9, "left");
  }
  function cHints(c, th, P, hw, hh, base) {
    legend(c, th, P.px, P.py - 4, [[th.cyan, "Error count", "Bars: how often each size of error happens. Error is output minus input."], [th.orange, "Noise trace", "The line at the bottom: the noise level over time."]]);
    hint(P.px, P.py, hw, hh + 12, "Error Histogram", "How often each size of error happens, in 16-bit steps. A wide, smooth bump means a smooth dither. Measured as output minus input.");
    hint(P.px + hw + 8, P.py, 24, hh, "Noise Meters", "Left and right level of the added noise, in dBFS. Measured as output minus input.");
    hint(P.px + hw + 34, P.py, 28, hh, "Noise Scale", "Scale for the noise meters, in dBFS.");
    hint(P.px, P.py + P.ph - 28, P.pw, 28, "Noise Floor Trace", "The level of the added noise over time, newest on the right. Measured as output minus input.");
  }
  // C, real: histogram of the error in 16-bit steps, noise meters, noise history
  function drawCReal(c, th, st, P) {
    const hh = P.ph - 44, hw = P.pw - 62, base = P.py + hh, mx = Math.max(1, ...st.hist);
    clipTo(c, P.px, P.py, hw, hh + 12);
    c.fillStyle = th.cyan;
    for (let b = 0; b < 31; b++) { const bh = (st.hist[b] / mx) * (hh - 6), bw = hw / 31; c.fillRect(P.px + b * bw + 0.5, base - bh, bw - 1, bh); }
    c.restore();
    c.fillStyle = th.scale; c.fillRect(P.px, base, hw, 1);
    [-2, -1, 0, 1, 2].forEach(l => txt(c, P.px + hw / 2 + l * hw / 6, base + 9, l ? fm(l) : "0", { color: th.scale, size: 8.5 }));
    txt(c, P.px + 2, P.py + 8, "Error  (out - in), 16-bit steps", { color: th.dispText, size: 8.5, align: "left" });
    cHints(c, th, P, hw, hh, base);
    sameNote(c, th, st, P.px + 2, P.py + 20, "left", true);
    const mx0 = P.px + hw + 8, f = d => (d + 130) / 60;
    meterV(c, th, mx0, P.py, 10, hh, f(st.ndL)); meterV(c, th, mx0 + 12, P.py, 10, hh, f(st.ndR));
    [-120, -100, -80].forEach(d => { const y = P.py + hh * (1 - f(d)); txt(c, mx0 + 26, y + 3, String(d), { color: th.scale, size: 8.5, align: "left" }); });
    txt(c, mx0 + 5, base + 9, "L", { color: th.dispText, size: 8.5 }); txt(c, mx0 + 17, base + 9, "R", { color: th.dispText, size: 8.5 });
    const sy = P.py + P.ph - 28, sh = 24;
    c.fillStyle = th.dline; c.fillRect(P.px, sy - 2, P.pw, 1);
    clipTo(c, P.px, sy, P.pw, sh);
    c.strokeStyle = th.orange; c.lineWidth = 1.5; c.beginPath();
    const n = Math.min(st.nh.length, Math.floor(P.pw));
    for (let i = 0; i < n; i++) { const e = st.nh[st.nh.length - 1 - i], x = P.px + P.pw - i, y = sy + sh - (sh - 11) * Math.min(1, Math.max(0, (e + 130) / 70));
      i ? c.lineTo(x, y) : c.moveTo(x, y); }
    c.stroke(); c.restore();
    txt(c, P.px + 2, sy + 8, "Noise floor over time", { color: th.dispText, size: 8.5, align: "left" });
  }

  // ---------- shared layout
  // the shared gain strip (its meters explain themselves on hover)
  function gs(c, th, x, st) { gainStrip(c, th, x, st); }
  function step(st, dt) {
    if (!st.pre) { st.pre = true; for (let i = 0; i < 560; i++) { st.t += 0.016; step0(st, 0.016); } }
    step0(st, dt);
    const d = drums(st.t), a = db(d.env * 0.8 + 0.03);
    st.inL = Math.max(a, st.inL - 24 * dt); st.outL = Math.max(a - 0.2, st.outL - 24 * dt);
  }

  function dials(c, th, ps, vals, W) {
    const n = ps.length;
    if (!n) { rr(c, W - 92, HEAD_H + 4, 88, DEVICE_H - 8, 3, th.panel); txt(c, W - 48, HEAD_H + 88, "No controls", { color: th.dim });
      return 96; }
    const rows = n <= 5 ? 1 : n <= 10 ? 2 : 3, cols = Math.ceil(n / rows), w = cols * 52;
    knobGrid(c, th, ps, { x: W - w - 4, y: HEAD_H + 4, w, h: DEVICE_H - 8 }, cols, vals);
    return w + 8;
  }
  function panel(c, th, w, readouts, dTitle, dText) {
    const x = 4, y = HEAD_H + 4, h = DEVICE_H - 8;
    rr(c, x, y, w, h, 3, th.display);
    menu(c, th, x + 4, y + 3, 104, "BuildATPDF"); arrows(c, th, x + 112, y + 3);
    c.fillStyle = th.dline; c.fillRect(x, y + 21, w, 1);
    let rx = x + w - 6;
    hint(x, y, w, h, dTitle || "Display", dText || "Shows what the effect does to the sound, measured from the input and the output.");
    readouts.slice().reverse().forEach(r => {
      const r0 = rx;
      txt(c, rx, y + 14, r[1], { color: r[2], align: "right" }); rx -= r[1].length * 5 + 4;
      txt(c, rx, y + 14, r[0], { color: th.dispText, align: "right" }); rx -= r[0].length * 5 + 10;
      hint(rx + 6, y + 3, r0 - rx, 15, r[3] || r[0], r[4] || "");
    });
    return { x, y, w, h, px: x + 6, py: y + 26, pw: w - 12, ph: h - 32, lx: x + 146, ly: y + 14 };
  }
  const clipTo = (c, x, y, w, h) => { c.save(); c.beginPath(); c.rect(x, y, w, h); c.clip(); };
  const fm = v => (v >= 0 ? "+" : "") + v.toFixed(1);

  // ---------- A: zoomed waveform
  function drawA(c, th, st, ps, vals) {
    const W = 600, dw = dials(c, th, ps, vals, W);
    gs(c, th, W, st);
    const P = panel(c, th, W - dw - 8, st.real ? [["Noise", ndTxt(st), th.orange, "Noise Level", "How loud the added noise is, in dBFS. Measured as output minus input."], ["Level", `${(st.lvl === undefined ? -120 : st.lvl).toFixed(1)} dBFS`, th.cyan, "Signal Level", "The average (RMS) level of the output, in dBFS."]]
      : [["Noise", `${st.nd.toFixed(1)} dBFS`, th.orange, "Noise Level", "How loud the added noise is, in dBFS. Measured as output minus input."], ["Level", `${st.amp.toFixed(1)} LSB`, th.cyan, "Signal Level", "The size of the test tone, in 16-bit steps (LSB)."]],
      "Zoomed Waveform", "Shows the input and the output zoomed in to single 16-bit steps, so you can see what dither adds.");
    if (!st.s) return;
    if (st.real) return drawAReal(c, th, st, P);
    const mid = P.py + P.ph / 2, sc = P.ph / 14;
    clipTo(c, P.px, P.py, P.pw, P.ph);
    c.lineWidth = 1;
    for (let l = -6; l <= 6; l++) { c.strokeStyle = l === 0 ? th.scale : th.dline; c.beginPath(); c.moveTo(P.px, mid - l * sc); c.lineTo(P.px + P.pw, mid - l * sc); c.stroke(); }
    c.strokeStyle = th.cyan; c.lineWidth = 1.5; c.beginPath();
    for (let i = 0; i < N; i++) { const x = P.px + i / (N - 1) * P.pw, y = mid - st.s[i] * sc; i ? c.lineTo(x, y) : c.moveTo(x, y); }
    c.stroke();
    c.strokeStyle = th.orange; c.lineWidth = 1.5; c.beginPath();
    for (let i = 0; i < N; i++) { const x0 = P.px + i / N * P.pw, x1 = P.px + (i + 1) / N * P.pw, y = mid - st.y[i] * sc;
      i ? c.lineTo(x0, y) : c.moveTo(x0, y); c.lineTo(x1, y); }
    c.stroke(); c.restore();
    [-4, 0, 4].forEach(l => txt(c, P.px + 1, mid - l * sc - 2, l ? fm(l) : "0", { color: th.scale, size: 8.5, align: "left" }));
    legend(c, th, P.x + 6, P.y + P.h - 3, [[th.cyan, "In", "The sound going into the effect, measured at its input."], [th.orange, "Out", "The sound coming out of the effect, measured at its output."]], { line: true });
    hint(P.px, P.py, P.pw, P.ph, "Input And Output Waveform", "A short piece of the sound, zoomed in to single 16-bit steps. Cyan is the input, orange is the output. Measured from the audio going in and out.");
    txt(c, P.x + P.w - 6, P.y + P.h - 3, "grid = 1 LSB", { color: th.scale, size: 8.5, align: "right" });
    hint(P.x + P.w - 70, P.y + P.h - 12, 66, 10, "Grid Size", "Each grid line is 1 step (LSB) of the 16-bit sample. A step is the smallest level a 16-bit file can store.");
  }

  // ---------- B: spectrum of the output
  function drawB(c, th, st, ps, vals) {
    const W = 620, dw = dials(c, th, ps, vals, W);
    gs(c, th, W, st);
    const P = panel(c, th, W - dw - 8, [["Floor", st.real ? (st.nd === undefined || st.nd <= -119 ? "<-119 dB" : `${st.nd.toFixed(0)} dB`) : `${(st.floor || -130).toFixed(0)} dB`, th.orange, "Noise Floor", "The average level of the noise the effect adds, in dB. Measured as output minus input."]],
      "Noise Spectrum", "Shows how loud the output is at each pitch, so you can see where the dither noise sits.");
    if (!st.spec) return;
    if (st.real) return drawBReal(c, th, st, P);
    const lo = -140, hi = -60, yOf = d => P.py + P.ph - 10 - (P.ph - 10) * (Math.min(hi, Math.max(lo, d)) - lo) / (hi - lo);
    const xOf = k => P.px + P.pw * k / (K - 1);
    clipTo(c, P.px, P.py, P.pw, P.ph);
    c.lineWidth = 1; c.strokeStyle = th.dline;
    for (let d = -120; d <= -80; d += 20) { c.beginPath(); c.moveTo(P.px, yOf(d)); c.lineTo(P.px + P.pw, yOf(d)); c.stroke(); }
    c.globalAlpha = 0.28; c.fillStyle = th.cyan; c.beginPath(); c.moveTo(xOf(0), P.py + P.ph - 10);
    for (let k = 0; k < K; k++) c.lineTo(xOf(k), yOf(st.spec[k]));
    c.lineTo(xOf(K - 1), P.py + P.ph - 10); c.fill(); c.globalAlpha = 1;
    c.strokeStyle = th.cyan; c.lineWidth = 1.5; c.beginPath();
    for (let k = 0; k < K; k++) k ? c.lineTo(xOf(k), yOf(st.spec[k])) : c.moveTo(xOf(k), yOf(st.spec[k]));
    c.stroke();
    c.strokeStyle = th.orange; c.lineWidth = 1; c.setLineDash && c.setLineDash([3, 3]);
    c.beginPath(); c.moveTo(P.px, yOf(st.floor)); c.lineTo(P.px + P.pw, yOf(st.floor)); c.stroke(); c.setLineDash && c.setLineDash([]);
    c.restore();
    for (let d = -120; d <= -80; d += 20) txt(c, P.px + P.pw - 2, yOf(d) - 2, String(d), { color: th.scale, size: 8.5, align: "right" });
    ["0", "5k", "10k", "15k", "20k"].forEach((s, i) => txt(c, P.px + 3 + (P.pw - 6) * i / 4, P.py + P.ph - 1, s, { color: th.scale, size: 8.5, align: i === 0 ? "left" : i === 4 ? "right" : "center" }));
    txt(c, xOf(4) + 6, Math.max(P.py + 9, yOf(st.spec[4]) + 3), "tone", { color: th.cyan, size: 9, align: "left" });
    legend(c, th, P.lx, P.ly, [[th.cyan, "Output", "The loudness of the output at each pitch (frequency). Measured from the output audio."], [th.orange, "Noise floor", "The dashed line: the average level of the added noise."]], { line: true });
    hint(P.px, P.py, P.pw, P.ph, "Output Spectrum", "Loudness at each pitch, low pitches on the left. The cyan peak is the test tone. Measured from the output audio.");
    hint(P.px, yOf(st.floor) - 3, P.pw, 6, "Noise Floor Line", "The dashed orange line is the average level of the noise, in dB.");
  }

  // ---------- C: error histogram + noise meters + history
  function drawC(c, th, st, ps, vals) {
    const W = 560, dw = dials(c, th, ps, vals, W);
    gs(c, th, W, st);
    const P0 = panel(c, th, W - dw - 8, [["SNR", st.real ? (st.snrTxt || "-") : `${st.snr.toFixed(0)} dB`, th.cyan, "Signal To Noise Ratio", "How far the signal is above the added noise, in dB. Measured as output level minus noise level."], ["Peak", `${(st.peak || 0).toFixed(1)} LSB`, th.orange, "Error Peak", "The biggest single error between output and input, in 16-bit steps (LSB)."]],
      "Error Meter", "Shows the error the effect adds (output minus input) as a histogram, noise meters and a trace over time.");
    const P = Object.assign({}, P0, { py: P0.py + 12, ph: P0.ph - 12 });
    if (!st.hist) return;
    if (st.real) return drawCReal(c, th, st, P);
    const hh = P.ph - 44, hw = P.pw - 62, base = P.py + hh;
    const mx = Math.max(1, ...st.hist);
    clipTo(c, P.px, P.py, hw, hh + 12);
    c.fillStyle = th.cyan;
    for (let b = 0; b < 31; b++) { const bh = (st.hist[b] / mx) * (hh - 6), bw = hw / 31; c.fillRect(P.px + b * bw + 0.5, base - bh, bw - 1, bh); }
    c.restore();
    c.fillStyle = th.scale; c.fillRect(P.px, base, hw, 1);
    [-2, -1, 0, 1, 2].forEach(l => txt(c, P.px + hw / 2 + l * hw / 6, base + 9, l ? fm(l) : "0", { color: th.scale, size: 8.5 }));
    txt(c, P.px + 2, P.py + 8, "Error  (out - in), LSB", { color: th.dispText, size: 8.5, align: "left" });
    cHints(c, th, P, hw, hh, base);
    // noise meters
    const mx0 = P.px + hw + 8, f = d => (d + 110) / 30;
    meterV(c, th, mx0, P.py, 10, hh, f(st.ndL)); meterV(c, th, mx0 + 12, P.py, 10, hh, f(st.ndR));
    [-100, -90, -80].forEach(d => { const y = P.py + hh * (1 - f(d)); txt(c, mx0 + 26, y + 3, String(d), { color: th.scale, size: 8.5, align: "left" }); });
    txt(c, mx0 + 5, base + 9, "L", { color: th.dispText, size: 8.5 }); txt(c, mx0 + 17, base + 9, "R", { color: th.dispText, size: 8.5 });
    // noise-floor history strip
    const sy = P.py + P.ph - 28, sh = 24;
    c.fillStyle = th.dline; c.fillRect(P.px, sy - 2, P.pw, 1);
    clipTo(c, P.px, sy, P.pw, sh);
    c.strokeStyle = th.orange; c.lineWidth = 1.5; c.beginPath();
    const n = Math.min(st.nh.length, Math.floor(P.pw));
    for (let i = 0; i < n; i++) { const e = st.nh[st.nh.length - 1 - i], x = P.px + P.pw - i, y = sy + sh - (sh - 11) * Math.min(1, Math.max(0, (e + 101) / 8));
      i ? c.lineTo(x, y) : c.moveTo(x, y); }
    c.stroke(); c.restore();
    txt(c, P.px + 2, sy + 8, "Noise floor over time", { color: th.dispText, size: 8.5, align: "left" });
  }

  DESIGNS["Dithers"] = {
    effect: "BuildATPDF",
    refs: [["SaturatorL12.png", "Saturator (waveform + curve display)"], ["EQEightL12.png", "EQ Eight (spectrum)"], ["UtilityL12.png", "Utility (meters)"]],
    lead: "Visual cue: the tiny error a dither adds, measured as output minus input, shown as a zoomed waveform, a noise spectrum and a noise-floor meter.",
    options: [
      { id: "A", name: "Zoomed waveform", short: "Waveform", width: 668, step, live,
        why: "A very quiet sine zoomed to bit level: the input line in cyan, the stepped output in orange, like the waveform view of Saturator.",
        bullets: ["Input and output waveform, grid = 1 LSB step", "Readouts: noise floor (dBFS) and signal level", "Driven by the audio in and the audio out of the device",
          "Live: input and output scope (m.inScope/scope), error strip = out - in in 16-bit steps, Noise = diffRmsDb, Level = outRmsDb (dBFS)"],
        draw: drawA },
      { id: "B", name: "Noise spectrum", short: "Spectrum", width: 688, step, live,
        why: "FFT spectrum of the output with a dashed line at the measured noise floor, in the style of EQ Eight's analyser.",
        bullets: ["FFT of the output, 0–20 kHz, -140 to -60 dB", "Dashed line = average noise floor", "Shows where the noise sits, so noise shaping is visible",
          "Live: cyan = specOut, orange = specDiff (added part), dashed = diffRmsDb; axis -120..0 dB, log frequency (48 bands, not a 128-bin FFT)"],
        draw: drawB },
      { id: "C", name: "Error meter", short: "Error", width: 628, step, live,
        why: "Histogram of the error (output minus input) beside two noise meters and a scrolling noise-floor trace.",
        bullets: ["Histogram of the difference between output and input", "Left/right noise meters and SNR readout", "Driven by the in-vs-out difference of each sample",
          "Live: histogram and L/R noise meters from scope out - in (64 samples per frame), SNR = outRmsDb - diffRmsDb, history = diffRmsDb"],
        draw: drawC },
    ],
  };
})();

